stimulus.text:
SELECT *
FROM   TBL
WHERE  COL IN (100, 200, 100);

SELECT COL1
FROM   TBL1
WHERE  COL1 <= ALL (SELECT COL2 FROM TBL2);

SELECT 주문일자, 상품코드, COUNT(*)
FROM   주문
GROUP  BY ROLLUP((주문일자, 상품코드));

SELECT NAME, SCORE,
______() OVER (ORDER BY SCORE DESC) AS RNK
FROM   TBL;

SELECT *
FROM  (SELECT DEPT_ID, SAL FROM EMP)
PIVOT (SUM(SAL) FOR DEPT_ID IN (10 AS A, 20 AS B, 30 AS C));

SELECT SALE_DATE, AMT,
SUM(AMT) OVER (ORDER BY SALE_DATE) AS CUM_AMT
FROM   SALES;

SELECT *
FROM PRODUCT
WHERE PROD_ID NOT IN (SELECT PARENT_ID FROM PRODUCT);

SELECT COL1 FROM TBL1
MINUS
SELECT COL2 FROM TBL2;

SELECT ENAME,
CASE WHEN SAL IS NULL THEN 100 ELSE SAL END AS RESULT
FROM EMP;

CREATE TABLE TAB (
COL1  NUMBER       NOT NULL,
COL2  VARCHAR2(10),
COL3  VARCHAR2(10) DEFAULT 'N',
COL4  DATE
);

SELECT (SELECT MAX(SAL) FROM EMP WHERE DEPT_ID = 30)
+ (SELECT MIN(SAL) FROM EMP WHERE DEPT_ID = 20 AND SAL IS NULL)
FROM   DUAL;

SELECT DEPTNO, PRODUCT, SUM(AMT)
FROM   SALES
GROUP BY GROUPING SETS ((DEPTNO, PRODUCT), (DEPTNO), ());

CREATE TABLE DEPT (
DEPT_ID    NUMBER PRIMARY KEY,
DEPT_NAME  VARCHAR2(20)
);

CREATE TABLE EMP (
EMP_ID    NUMBER PRIMARY KEY,
EMP_NAME  VARCHAR2(20),
DEPT_ID   NUMBER,
CONSTRAINT FK_DEPT FOREIGN KEY (DEPT_ID) REFERENCES DEPT(DEPT_ID)
);

INSERT INTO DEPT VALUES (10, '개발팀');
INSERT INTO EMP VALUES (1, 'KIM', 10);

SELECT SALE_DATE, AMT,
AMT - LAG(AMT) OVER (ORDER BY SALE_DATE) AS DIFF
FROM   SALES;

CREATE TABLE TBL (NUM NUMBER);

INSERT INTO TBL VALUES (1);
SAVEPOINT SP1;

INSERT INTO TBL VALUES (2);
INSERT INTO TBL VALUES (3);

ROLLBACK TO SP1;

INSERT INTO TBL VALUES (4);

COMMIT;

SELECT COUNT(*) FROM TBL;

questions.explanation:
정답은 ③ 2이다. ROLLBACK TO SAVEPOINT는 해당 저장점 이후의 변경만 취소하고 그 이전 변경은 유지한다.
1단계: INSERT 1 → 테이블 {1}
2단계: SAVEPOINT SP1 지정
3단계: INSERT 2, INSERT 3 → {1, 2, 3}
4단계: ROLLBACK TO SP1 → SP1 이후의 2, 3만 취소 → {1}
5단계: INSERT 4 → {1, 4}
6단계: COMMIT → {1, 4} 확정
따라서 COUNT(*) = 2이다.
① 0은 ROLLBACK TO SP1이 트랜잭션 전체를 취소한다고 본 경우로, 저장점 이전 변경(1)은 유지된다.
② 1은 ROLLBACK 이후에 실행한 INSERT 4를 빠뜨린 경우로, 4는 COMMIT 전에 수행되어 함께 확정된다.
④ 3은 롤백된 2, 3 중 일부가 남았다고 본 경우로, SP1 이후 변경은 모두 취소된다.
보충: 저장점으로 롤백해도 트랜잭션은 종료되지 않고 이어진다. 이후 COMMIT 시 저장점 이전 변경과 롤백 뒤 새 변경이 함께 확정된다.
